UPDATE lessons SET title='Year 3, Week 29, Lesson 2: Coding a simple game', data=json_patch(data,'{"child_mission":"Coding a simple game needs a goal, controls (events), win/lose conditions and lots of testing with friends as players.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same science idea to a new object or material, then compare two pieces of evidence for strength.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nList goal, one control and one win condition for a tiny catcher game.\n\nFEEDBACK\ne.g. catch fruit; left/right keys; catch 5 to win.\n\nWATCH FOR\nA game with no way to win or lose is unfinished for this lesson’s purpose.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nDesign and build a minimal game (digital or board-with-algorithm cards). Playtest with a partner twice. Record one bug fixed after playtest.\n\nWrite a short reflection naming one observation or step you corrected and why.","interactive_activities":null,"learning_area":"Science and Technology","learning_intention":"Coding a simple game needs a goal, controls (events), win/lose conditions and lots of testing with friends as players.","lesson_number":2,"lesson_role":"Apply and make","materials":["Paper or typed answer space","Pencil","Optional: safe everyday objects for observation"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["ST2-DDT-02"],"parent_notes":"Parent: Marking guidance for the independent task: Design and build a minimal game (digital or board-with-algorithm cards). Playtest with a partner twice. Record one bug fixed after playtest. Accept equivalent original responses that show the same skill.\n\nParent: Written mo